function applyTheme(themeName) {
  const palette = themeName === "light" ? LIGHT : themeName === "medio" ? MEDIO : DARK;
  Object.assign(C, palette);
  LOGO.src = `data:image/png;base64,${themeName === "dark" ? LOGO_B64 : LOGO_B64_LIGHT}`;
}

