function computeSubStatus(profile) {
  if (!profile) return { label: "Sin datos", color: C.grey };
  if (profile.vitalicio) return { label: "Vitalicia", color: C.blue };
  if (!profile.fecha_vencimiento) return { label: "Usuario de prueba", color: C.blue };
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const venc = new Date(profile.fecha_vencimiento + "T00:00:00");
  if (venc < today) return { label: "Vencida", color: C.red };
  return profile.pago ? { label: "Activa", color: C.green } : { label: "Prueba gratis", color: C.blue };
}

function computePlanLabel(profile) {
  if (!profile) return "—";
  if (profile.vitalicio) return "Vitalicio";
  if (profile.es_admin) return "Admin";
  if (!profile.pago) return "Prueba gratuita";
  if (!profile.fecha_renovacion || !profile.fecha_vencimiento) return "Membresía";
  const inicio = new Date(profile.fecha_renovacion + "T00:00:00");
  const fin = new Date(profile.fecha_vencimiento + "T00:00:00");
  const meses = Math.round((fin - inicio) / (1000 * 60 * 60 * 24 * 30));
  if (meses >= 11) return "Membresía X12";
  if (meses >= 5) return "Membresía X6";
  if (meses >= 2) return "Membresía X3";
  return "Membresía";
}

function daysUntilVencimiento(profile) {
  if (!profile || profile.vitalicio || !profile.fecha_vencimiento) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const venc = new Date(profile.fecha_vencimiento + "T00:00:00");
  return Math.round((venc - today) / (1000 * 60 * 60 * 24));
}

const NIVELES_CONTENIDO = [
  { value: "prueba", label: "Usuario Prueba", rank: 0 },
  { value: "esencial", label: "Esencial", rank: 1 },
  { value: "trader", label: "Trader", rank: 2 },
  { value: "pro", label: "Pro", rank: 3 },
  { value: "full", label: "Full Access", rank: 4 },
];

function rankNivel(value) {
  const found = NIVELES_CONTENIDO.find((n) => n.value === value);
  return found ? found.rank : 0;
}

function labelNivel(value) {
  const found = NIVELES_CONTENIDO.find((n) => n.value === value);
  return found ? found.label : "Usuario Prueba";
}

function nivelEfectivoUsuario(profile) {
  if (profile?.es_admin) return 99;
  return rankNivel(profile?.nivel_contenido || "prueba");
}

