function LoginView({ onLogin, onSignup }) {
  const [mode, setMode] = useState("login"); // "login" | "signup" | "signup-done"
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [esComunidad, setEsComunidad] = useState(null); // null | true | false
  const [discordUsuario, setDiscordUsuario] = useState("");
  const [termsChecked, setTermsChecked] = useState(false);
  const [showTerms, setShowTerms] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const inputStyle = { backgroundColor: C.card, color: C.text, border: `1px solid ${C.border}` };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      if (mode === "login") {
        await onLogin(email.trim(), password);
      } else {
        await onSignup(email.trim(), password, nombre.trim(), !!esComunidad, esComunidad ? discordUsuario.trim() : "");
        setMode("signup-done");
      }
    } catch (err) {
      setError(err.message || "Ocurrió un error");
    } finally {
      setLoading(false);
    }
  };

  if (showTerms) {
    return <TermsPageView onBack={() => setShowTerms(false)} />;
  }

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" style={{ backgroundColor: C.bg }}>
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `url(${LOGIN_BG})`,
          backgroundSize: "cover",
          backgroundPosition: "88% center",
        }}
      />
      <div
        className="absolute inset-0"
        style={{
          background:
            "linear-gradient(180deg, rgba(6,8,10,0.40) 0%, rgba(6,8,10,0.68) 45%, rgba(6,8,10,0.94) 100%)",
        }}
      />
      <div className="relative z-10 min-h-full flex flex-col justify-center px-6 py-10">
      <div className="max-w-sm mx-auto w-full">
        <div className="flex flex-col items-center mb-6">
          <div className="mb-4">
            <BrandBadge size={84} />
          </div>
          <span className="text-[15px] font-bold tracking-wide" style={{ color: C.text }}>TRADER APP</span>
          <span className="text-xs text-center mt-1 px-4" style={{ color: C.textDim }}>
            Todas las herramientas de un trader profesional en un solo lugar
          </span>
        </div>

        {mode === "signup-done" ? (
          <div className="rounded-2xl p-5 text-center" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
            <Check size={28} color={C.green} className="mx-auto mb-2" />
            <p className="text-sm mb-1" style={{ color: C.text }}>¡Cuenta creada!</p>
            <p className="text-xs" style={{ color: C.textDim }}>
              {REQUIRE_APPROVAL
                ? "Un admin tiene que aprobar tu acceso antes de que puedas ingresar. Te va a avisar por su cuenta cuando esté listo."
                : "Ya podés iniciar sesión con tu email y contraseña."}
            </p>
            <button
              onClick={() => setMode("login")}
              className="w-full rounded-xl py-3 text-sm font-semibold mt-4"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            >
              Ir a iniciar sesión
            </button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} autoComplete="on">
            {mode === "signup" && (
              <div className="mb-3">
                <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>NOMBRE COMPLETO</label>
                <input
                  name="name"
                  autoComplete="name"
                  value={nombre}
                  onChange={(e) => setNombre(e.target.value)}
                  className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
                  style={inputStyle}
                />
              </div>
            )}
            {mode === "signup" && (
              <div className="mb-3">
                <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
                  ¿SOS MIEMBRO DE LA COMUNIDAD?
                </label>
                <div className="flex gap-2 mt-1">
                  {[{ v: true, l: "Sí" }, { v: false, l: "No" }].map((opt) => (
                    <button
                      key={opt.l}
                      type="button"
                      onClick={() => setEsComunidad(opt.v)}
                      className="flex-1 rounded-xl py-2.5 text-sm font-semibold"
                      style={{
                        backgroundColor: esComunidad === opt.v ? C.green : C.card,
                        color: esComunidad === opt.v ? "#08090B" : C.textDim,
                        border: `1px solid ${C.border}`,
                      }}
                    >
                      {opt.l}
                    </button>
                  ))}
                </div>
              </div>
            )}
            {mode === "signup" && esComunidad === true && (
              <div className="mb-3">
                <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>USUARIO DE DISCORD</label>
                <input
                  name="discord"
                  value={discordUsuario}
                  onChange={(e) => setDiscordUsuario(e.target.value)}
                  placeholder="tu_usuario"
                  className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
                  style={inputStyle}
                />
              </div>
            )}
            <div className="mb-3">
              <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>EMAIL</label>
              <input
                type="email"
                name="email"
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
                style={inputStyle}
              />
            </div>
            <div className="mb-5">
              <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>CONTRASEÑA</label>
              <div className="relative mt-1">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  autoComplete={mode === "login" ? "current-password" : "new-password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full rounded-xl pl-4 pr-11 py-3 text-[15px] outline-none"
                  style={inputStyle}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword((v) => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2"
                  aria-label={showPassword ? "Ocultar contraseña" : "Mostrar contraseña"}
                >
                  {showPassword ? <EyeOff size={18} color={C.textDim} /> : <Eye size={18} color={C.textDim} />}
                </button>
              </div>
            </div>

            {mode === "signup" && (
              <label className="flex items-start gap-2.5 mb-5 cursor-pointer">
                <input
                  type="checkbox"
                  checked={termsChecked}
                  onChange={(e) => setTermsChecked(e.target.checked)}
                  className="mt-0.5 w-4 h-4 shrink-0"
                />
                <span className="text-xs" style={{ color: C.textDim }}>
                  Leí y acepto los{" "}
                  <button
                    type="button"
                    onClick={() => setShowTerms(true)}
                    className="underline font-medium"
                    style={{ color: C.blue }}
                  >
                    Términos y Condiciones
                  </button>
                </span>
              </label>
            )}

            {error && <p className="text-sm text-center mb-4" style={{ color: C.red }}>{error}</p>}

            {(() => {
              const blocked =
                loading ||
                !email ||
                !password ||
                (mode === "signup" &&
                  (!nombre || esComunidad === null || (esComunidad === true && !discordUsuario.trim()) || !termsChecked));
              return (
                <button
                  type="submit"
                  disabled={blocked}
                  className="w-full rounded-2xl py-4 text-[15px] font-semibold"
                  style={{
                    backgroundColor: blocked ? C.borderSoft : C.green,
                    color: blocked ? C.textDim : "#08090B",
                  }}
                >
                  {loading ? "Un momento..." : mode === "login" ? "Ingresar" : "Crear cuenta"}
                </button>
              );
            })()}

            <button
              type="button"
              onClick={() => {
                setMode(mode === "login" ? "signup" : "login");
                setError(null);
              }}
              className="w-full text-center text-xs mt-4"
              style={{ color: C.blue }}
            >
              {mode === "login" ? "¿No tenés cuenta? Creá una" : "¿Ya tenés cuenta? Iniciá sesión"}
            </button>
          </form>
        )}
      </div>
      </div>
    </div>
  );
}

function PaymentProofForm({ userId, initialMeses, onClose, onSent }) {
  const [file, setFile] = useState(null);
  const [planMeses, setPlanMeses] = useState(initialMeses || null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async () => {
    if (!file || !planMeses) return;
    setSubmitting(true);
    setError(null);
    try {
      const url = await uploadPaymentProof(file);
      await createComprobante(userId, url, planMeses);
      onSent();
      onClose();
    } catch (err) {
      setError(err.message || "No se pudo enviar el comprobante");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center"
      style={{ backgroundColor: "rgba(0,0,0,0.6)" }}
      onClick={onClose}
    >
      <div
        className="rounded-t-3xl w-full max-w-md p-6 max-h-[85vh] overflow-y-auto"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, borderBottom: "none" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <span className="text-[15px] font-semibold" style={{ color: C.text }}>Subir comprobante de pago</span>
          <button onClick={onClose}>
            <X size={20} color={C.textDim} />
          </button>
        </div>

        <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
          ¿QUÉ PLAN PAGASTE?
        </label>
        <div className="flex flex-col gap-2 mt-1 mb-4">
          {PLANES_PRO.map((p) => (
            <button
              key={p.id}
              onClick={() => setPlanMeses(p.meses)}
              className="rounded-xl px-4 py-3 text-left flex items-center justify-between"
              style={{
                backgroundColor: planMeses === p.meses ? C.greenSoft : C.cardAlt,
                border: `1px solid ${planMeses === p.meses ? C.green : C.border}`,
              }}
            >
              <span className="text-sm font-semibold" style={{ color: C.text }}>{p.label}</span>
              <span className="text-xs" style={{ color: C.textDim }}>${p.precio} USD/USDT · {p.periodo}</span>
            </button>
          ))}
        </div>

        <label
          className="flex items-center justify-center gap-2 rounded-xl py-6 cursor-pointer mb-4"
          style={{ backgroundColor: C.cardAlt, border: `1px dashed ${C.border}` }}
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            const f = e.dataTransfer.files?.[0];
            if (f) setFile(f);
          }}
        >
          <UploadCloud size={18} color={C.textDim} />
          <span className="text-sm" style={{ color: C.textDim }}>
            {file ? file.name : "Elegir imagen del comprobante"}
          </span>
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => setFile(e.target.files?.[0] || null)}
          />
        </label>

        {error && <p className="text-sm text-center mb-3" style={{ color: C.red }}>{error}</p>}

        <button
          onClick={handleSubmit}
          disabled={!file || !planMeses || submitting}
          className="w-full rounded-2xl py-4 text-[15px] font-semibold"
          style={{
            backgroundColor: file && planMeses && !submitting ? C.green : C.borderSoft,
            color: file && planMeses && !submitting ? "#08090B" : C.textDim,
          }}
        >
          {submitting ? "Enviando..." : "Enviar comprobante"}
        </button>
        <p className="text-[11px] text-center mt-3" style={{ color: C.textDim }}>
          Un admin lo va a revisar y aprobar. Tu cuenta se reactiva automáticamente al aprobarse.
        </p>
      </div>
    </div>
  );
}

function SubscriptionExpiredView({ userId, accessToken, onLogout, onEnterPreview }) {
  const [hasPending, setHasPending] = useState(null); // null = cargando
  const [showForm, setShowForm] = useState(false);

  const check = () => {
    setHasPending(null);
    fetchMyPendingComprobante(userId, accessToken)
      .then((row) => setHasPending(!!row))
      .catch(() => setHasPending(false));
  };

  React.useEffect(() => {
    check();
  }, []);

  return (
    <div className="fixed inset-0 z-50 flex flex-col items-center justify-center px-6 text-center" style={{ backgroundColor: C.bg }}>
      <div className="mb-5"><BrandBadge size={80} /></div>
      <div className="w-16 h-16 rounded-full flex items-center justify-center mb-4" style={{ backgroundColor: hasPending === true ? "rgba(240,180,41,0.14)" : C.redSoft }}>
        <span style={{ fontSize: 28 }}>{hasPending === true ? "⏳" : "🔒"}</span>
      </div>
      <p className="text-[15px] font-semibold mb-2" style={{ color: C.text }}>
        {hasPending === true ? "Pendiente de aprobación" : "Tu suscripción venció"}
      </p>

      {hasPending === true ? (
        <p className="text-sm mb-6 max-w-xs" style={{ color: C.textDim }}>
          Ya enviaste un comprobante de pago — está pendiente de revisión por un admin. Tu cuenta se reactiva sola apenas se apruebe.
        </p>
      ) : (
        <p className="text-sm mb-6 max-w-xs" style={{ color: C.textDim }}>
          Subí tu comprobante de pago para que un admin lo revise y tu cuenta se reactive.
        </p>
      )}

      <div className="flex flex-col gap-3 w-full max-w-xs">
        {hasPending === false && (
          <button
            onClick={() => setShowForm(true)}
            className="rounded-2xl py-3.5 text-sm font-semibold"
            style={{ backgroundColor: C.green, color: "#08090B" }}
          >
            Subir comprobante de pago
          </button>
        )}
        {hasPending === true && (
          <button
            onClick={onEnterPreview}
            className="rounded-2xl py-3.5 text-sm font-semibold"
            style={{ backgroundColor: C.green, color: "#08090B" }}
          >
            Ir a la app
          </button>
        )}
        <button
          onClick={onLogout}
          className="rounded-2xl py-3.5 text-sm font-semibold"
          style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
        >
          Cerrar sesión
        </button>
      </div>

      {showForm && (
        <PaymentProofForm
          userId={userId}
          onClose={() => setShowForm(false)}
          onSent={check}
        />
      )}
    </div>
  );
}

function PersonalDataPopup({ profile, accessToken, onClose, onSaved }) {
  const [nombre, setNombreLocal] = useState(profile?.nombre || "");
  const [telefono, setTelefono] = useState(profile?.telefono || "");
  const [discordUsuario, setDiscordUsuario] = useState(profile?.discord_usuario || "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  const inputStyle = { backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await updateProfile(
        profile.id,
        { nombre: nombre.trim(), telefono: telefono.trim(), discord_usuario: discordUsuario.trim() || null },
        accessToken
      );
      onSaved(nombre.trim());
      onClose();
    } catch (err) {
      setError(err.message || "No se pudo guardar");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center"
      style={{ backgroundColor: "rgba(0,0,0,0.6)" }}
    >
      <div
        className="rounded-t-3xl w-full max-w-md p-6"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, borderBottom: "none" }}
      >
        <div className="flex items-center justify-between mb-2">
          <span className="text-[15px] font-semibold" style={{ color: C.text }}>Actualizá tus datos</span>
          <button onClick={onClose}>
            <X size={20} color={C.textDim} />
          </button>
        </div>
        <p className="text-xs mb-4" style={{ color: C.textDim }}>
          Nos ayuda a contactarte si hace falta. Podés completarlo ahora o más tarde desde Configuración.
        </p>

        <div className="mb-3">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>NOMBRE COMPLETO</label>
          <input
            value={nombre}
            onChange={(e) => setNombreLocal(e.target.value)}
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
            style={inputStyle}
          />
        </div>
        <div className="mb-3">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>TELÉFONO</label>
          <input
            value={telefono}
            onChange={(e) => setTelefono(e.target.value)}
            placeholder="+54 9 11 1234-5678"
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
            style={inputStyle}
          />
        </div>
        <div className="mb-3">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>EMAIL</label>
          <input
            value={profile?.email || ""}
            disabled
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none opacity-60"
            style={inputStyle}
          />
        </div>
        <div className="mb-4">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>USUARIO DE DISCORD (opcional)</label>
          <input
            value={discordUsuario}
            onChange={(e) => setDiscordUsuario(e.target.value)}
            placeholder="tu_usuario"
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
            style={inputStyle}
          />
        </div>

        {error && <p className="text-sm text-center mb-3" style={{ color: C.red }}>{error}</p>}

        <button
          onClick={handleSave}
          disabled={saving || !nombre.trim()}
          className="w-full rounded-2xl py-4 text-[15px] font-semibold mb-2"
          style={{ backgroundColor: C.green, color: "#08090B" }}
        >
          {saving ? "Guardando..." : "Guardar"}
        </button>
        <button onClick={onClose} className="w-full text-center text-xs py-2" style={{ color: C.textDim }}>
          Recordarme más tarde
        </button>
      </div>
    </div>
  );
}

function FlyerPopup({ flyers, onClose }) {
  const [index, setIndex] = useState(0);
  const flyer = flyers[index];
  const esUltimo = index >= flyers.length - 1;
  const esPrimero = index === 0;

  const avanzar = () => {
    if (esUltimo) onClose();
    else setIndex((i) => i + 1);
  };

  const irSiguiente = (e) => {
    e.stopPropagation();
    if (!esUltimo) setIndex((i) => i + 1);
  };

  const irAnterior = (e) => {
    e.stopPropagation();
    if (!esPrimero) setIndex((i) => i - 1);
  };

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center p-6"
      style={{ backgroundColor: "rgba(0,0,0,0.75)" }}
      onClick={avanzar}
    >
      <div className="w-full max-w-sm relative flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
        {flyers.length > 1 && (
          <button
            onClick={irAnterior}
            disabled={esPrimero}
            className="w-8 h-8 rounded-full flex items-center justify-center shrink-0"
            style={{ backgroundColor: "rgba(255,255,255,0.12)", opacity: esPrimero ? 0.3 : 1 }}
          >
            <ChevronLeft size={18} color="#fff" />
          </button>
        )}
        <div className="flex-1 min-w-0 relative">
          <button
            onClick={onClose}
            className="absolute -top-3 -right-3 w-8 h-8 rounded-full flex items-center justify-center z-10"
            style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
          >
            <X size={16} color={C.text} />
          </button>
          <div className="rounded-2xl overflow-hidden" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
            <img src={flyer.imagen_url} alt="Novedad" className="w-full object-cover" />
            {(flyer.texto || flyer.enlace) && (
              <div className="p-4">
                {flyer.texto && (
                  <p className="text-sm text-center mb-3" style={{ color: C.text }}>{flyer.texto}</p>
                )}
                {flyer.enlace && (
                  <a
                    href={flyer.enlace}
                    target="_blank"
                    rel="noreferrer"
                    onClick={avanzar}
                    className="block w-full text-center rounded-xl py-3 text-sm font-semibold"
                    style={{ backgroundColor: C.green, color: "#08090B" }}
                  >
                    Ver más
                  </a>
                )}
              </div>
            )}
          </div>
          {flyers.length > 1 && (
            <div className="flex items-center justify-center gap-1.5 mt-4">
              {flyers.map((_, i) => (
                <div
                  key={i}
                  className="rounded-full"
                  style={{
                    width: i === index ? 16 : 6,
                    height: 6,
                    backgroundColor: i === index ? "#fff" : "rgba(255,255,255,0.4)",
                    transition: "width 0.2s",
                  }}
                />
              ))}
            </div>
          )}
        </div>
        {flyers.length > 1 && (
          <button
            onClick={irSiguiente}
            disabled={esUltimo}
            className="w-8 h-8 rounded-full flex items-center justify-center shrink-0"
            style={{ backgroundColor: "rgba(255,255,255,0.12)", opacity: esUltimo ? 0.3 : 1 }}
          >
            <ChevronRight size={18} color="#fff" />
          </button>
        )}
      </div>
    </div>
  );
}

function FlyerAdminView({ onBack, accessToken }) {
  const [current, setCurrent] = useState([]);
  const [loading, setLoading] = useState(true);
  const [file, setFile] = useState(null);
  const [enlace, setEnlace] = useState("");
  const [texto, setTexto] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [quitandoId, setQuitandoId] = useState(null);

  const load = () => {
    setLoading(true);
    fetchActiveFlyers()
      .then(setCurrent)
      .finally(() => setLoading(false));
  };

  React.useEffect(() => {
    load();
  }, []);

  const handlePublish = async () => {
    if (!file) return;
    setSubmitting(true);
    setError(null);
    try {
      const url = await uploadFlyerImage(file);
      await createFlyer(url, enlace.trim(), texto.trim(), accessToken);
      setFile(null);
      setEnlace("");
      setTexto("");
      load();
    } catch (err) {
      setError(err.message || "No se pudo publicar el flyer");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeactivate = async (id) => {
    setQuitandoId(id);
    try {
      await deactivateFlyer(id, accessToken);
      load();
    } finally {
      setQuitandoId(null);
    }
  };

  const puedeAgregarMas = current.length < 3;

  return (
    <div className="max-w-md mx-auto">
      <ScreenHeader title="Flyer / Promociones" onBack={onBack} />

      {loading && <p className="text-sm text-center py-6" style={{ color: C.textDim }}>Cargando...</p>}

      {!loading && current.length > 0 && (
        <div className="mb-5">
          <div className="text-xs font-semibold mb-3" style={{ color: C.green }}>
            FLYERS ACTIVOS AHORA ({current.length}/3)
          </div>
          <div className="flex flex-col gap-3">
            {current.map((f) => (
              <div key={f.id} className="rounded-2xl overflow-hidden" style={{ backgroundColor: C.card, border: `1px solid ${C.green}` }}>
                <img src={f.imagen_url} alt="Flyer activo" className="w-full h-32 object-cover" />
                <div className="px-4 py-3">
                  {f.texto && <p className="text-xs mb-2" style={{ color: C.text }}>{f.texto}</p>}
                  {f.enlace && <div className="text-xs mb-3 truncate" style={{ color: C.textDim }}>{f.enlace}</div>}
                  <button
                    onClick={() => handleDeactivate(f.id)}
                    disabled={quitandoId === f.id}
                    className="w-full rounded-xl py-2.5 text-sm font-semibold"
                    style={{ backgroundColor: C.redSoft, color: C.red }}
                  >
                    {quitandoId === f.id ? "Quitando..." : "Quitar este flyer"}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
      {!loading && current.length === 0 && (
        <p className="text-sm text-center mb-5" style={{ color: C.textDim }}>No hay ningún flyer activo ahora mismo.</p>
      )}

      {puedeAgregarMas ? (
        <>
          <div className="text-[11px] tracking-widest font-semibold mb-3" style={{ color: C.textDim }}>
            PUBLICAR UN NUEVO FLYER
          </div>

          <label
            className="flex items-center justify-center gap-2 rounded-xl py-6 cursor-pointer mb-3"
            style={{ backgroundColor: C.cardAlt, border: `1px dashed ${C.border}` }}
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => {
              e.preventDefault();
              const f = e.dataTransfer.files?.[0];
              if (f) setFile(f);
            }}
          >
            <UploadCloud size={18} color={C.textDim} />
            <span className="text-sm" style={{ color: C.textDim }}>{file ? file.name : "Elegir imagen del flyer"}</span>
            <input type="file" accept="image/*" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
          </label>

          <div className="mb-3">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
              TEXTO (opcional)
            </label>
            <textarea
              value={texto}
              onChange={(e) => setTexto(e.target.value)}
              placeholder="Ej: 20% de descuento en el plan X6 esta semana"
              rows={2}
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none resize-none"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          <div className="mb-4">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
              LINK "VER MÁS" (opcional)
            </label>
            <input
              value={enlace}
              onChange={(e) => setEnlace(e.target.value)}
              placeholder="https://..."
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          {error && <p className="text-sm text-center mb-3" style={{ color: C.red }}>{error}</p>}

          <button
            onClick={handlePublish}
            disabled={!file || submitting}
            className="w-full rounded-2xl py-4 text-[15px] font-semibold"
            style={{
              backgroundColor: file && !submitting ? C.green : C.borderSoft,
              color: file && !submitting ? "#08090B" : C.textDim,
            }}
          >
            {submitting ? "Publicando..." : "Publicar flyer"}
          </button>
          <p className="text-[11px] text-center mt-3" style={{ color: C.textDim }}>
            Se muestran como un popup apenas alguien abre la app, uno tras otro. Podés tener hasta 3 al mismo tiempo.
          </p>
        </>
      ) : (
        <p className="text-sm text-center py-4" style={{ color: C.textDim }}>
          Ya tenés 3 flyers activos, el máximo permitido. Quitá alguno para poder publicar uno nuevo.
        </p>
      )}
    </div>
  );
}

