function RachaDiaria({ signals }) {
  const [offset, setOffset] = useState(0); // 0 = últimos 10 días hasta hoy; mayor = más atrás en el tiempo

  const dias = [];
  const hoy = new Date();
  for (let i = 9 + offset; i >= offset; i--) {
    const d = new Date(hoy);
    d.setDate(d.getDate() - i);
    d.setHours(0, 0, 0, 0);
    dias.push(d);
  }

  const MESES = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  const rangoLabel = `${dias[0].getDate()} ${MESES[dias[0].getMonth()]} – ${dias[9].getDate()} ${MESES[dias[9].getMonth()]}`;

  const resultadosDelDia = (dia) => {
    const siguiente = new Date(dia);
    siguiente.setDate(siguiente.getDate() + 1);
    return signals
      .filter((s) => {
        if (!s.createdAt) return false;
        if (!["ganada", "perdida", "be", "descartada"].includes(s.estado)) return false;
        const f = new Date(s.createdAt);
        return f >= dia && f < siguiente;
      })
      .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
      .map((s) => ({ estado: s.estado, estadoOp2: s.estadoOp2 || null }));
  };

  const todosLosResultados = [];
  signals.forEach((s) => {
    if (s.estado === "ganada" || s.estado === "perdida") todosLosResultados.push(s.estado);
    if (s.estadoOp2 === "ganada" || s.estadoOp2 === "perdida") todosLosResultados.push(s.estadoOp2);
  });
  const ganadasCount = todosLosResultados.filter((r) => r === "ganada").length;
  const perdidasCount = todosLosResultados.filter((r) => r === "perdida").length;
  const decisivas = ganadasCount + perdidasCount;
  const porcentajeAcierto = decisivas > 0 ? Math.round((ganadasCount / decisivas) * 100) : null;

  return (
    <div className="rounded-2xl px-4 py-4 mb-4" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
      <div className="flex items-center justify-between mb-3">
        <button
          onClick={() => setOffset((o) => o + 10)}
          className="flex items-center justify-center w-6 h-6 rounded-full shrink-0"
          style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
        >
          <ChevronLeft size={14} color={C.textDim} />
        </button>
        <div className="text-center">
          <div className="flex items-center justify-center gap-2">
            <span className="text-[11px] tracking-widest font-semibold" style={{ color: C.textDim }}>
              RESUMEN DE TRADES
            </span>
            {porcentajeAcierto !== null && (
              <span
                className="text-[11px] font-bold px-1.5 py-0.5 rounded-full"
                style={{
                  color: porcentajeAcierto >= 50 ? C.green : C.red,
                  backgroundColor: porcentajeAcierto >= 50 ? C.greenSoft : C.redSoft,
                }}
              >
                {porcentajeAcierto}%
              </span>
            )}
          </div>
          <div className="text-[10px] mt-0.5" style={{ color: C.textDim }}>{rangoLabel}</div>
        </div>
        <button
          onClick={() => setOffset((o) => Math.max(0, o - 10))}
          disabled={offset === 0}
          className="flex items-center justify-center w-6 h-6 rounded-full shrink-0"
          style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, opacity: offset === 0 ? 0.35 : 1 }}
        >
          <ChevronRight size={14} color={C.textDim} />
        </button>
      </div>
      <div className="flex items-start justify-between">
        {dias.map((d, i) => {
          const resultados = resultadosDelDia(d);
          const esHoy = d.toDateString() === hoy.toDateString();
          return (
            <div key={i} className="flex flex-col items-center gap-1.5">
              <span
                className="text-[10px] font-semibold w-5 h-5 flex items-center justify-center rounded-full"
                style={{
                  color: esHoy ? "#08090B" : C.textDim,
                  backgroundColor: esHoy ? C.green : "transparent",
                }}
              >
                {d.getDate()}
              </span>
              <div className="flex flex-col items-center gap-1 min-h-[18px] justify-start">
                {Array.from({ length: Math.max(5, resultados.length) }).map((_, j) => {
                  const r = resultados[j];
                  const iconoDe = (est) => {
                    if (est === "ganada") return { Icon: Check, color: C.green };
                    if (est === "be") return { Icon: Dices, color: "#FFFFFF" };
                    if (est === "descartada") return { Icon: Ban, color: C.textDim };
                    return { Icon: X, color: C.red };
                  };
                  return (
                    <div key={j} className="flex items-center justify-center gap-0.5" style={{ minHeight: 14 }}>
                      {!r ? (
                        <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: C.border }} />
                      ) : r.estadoOp2 ? (
                        <>
                          {(() => {
                            const { Icon, color } = iconoDe(r.estado);
                            return <Icon size={12} color={color} strokeWidth={3} />;
                          })()}
                          {(() => {
                            const { Icon, color } = iconoDe(r.estadoOp2);
                            return <Icon size={12} color={color} strokeWidth={3} />;
                          })()}
                        </>
                      ) : (
                        (() => {
                          const { Icon, color } = iconoDe(r.estado);
                          return <Icon size={14} color={color} strokeWidth={3} />;
                        })()
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
      <div className="flex items-center gap-4 mt-3 pt-3 justify-center" style={{ borderTop: `1px solid ${C.borderSoft}` }}>
        <div className="flex items-center gap-1">
          <Check size={11} color={C.green} strokeWidth={3} />
          <span className="text-[10px]" style={{ color: C.textDim }}>Ganado</span>
        </div>
        <div className="flex items-center gap-1">
          <X size={11} color={C.red} strokeWidth={3} />
          <span className="text-[10px]" style={{ color: C.textDim }}>Perdido</span>
        </div>
        <div className="flex items-center gap-1">
          <Dices size={11} color="#FFFFFF" strokeWidth={3} />
          <span className="text-[10px]" style={{ color: C.textDim }}>BE</span>
        </div>
        <div className="flex items-center gap-1">
          <Ban size={11} color={C.textDim} strokeWidth={2.5} />
          <span className="text-[10px]" style={{ color: C.textDim }}>Descartada</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: C.border }} />
          <span className="text-[10px]" style={{ color: C.textDim }}>Sin trades</span>
        </div>
      </div>
    </div>
  );
}

