function UserEditForm({ user, onClose, onSaved, accessToken }) {
  const [nombre, setNombre] = useState(user.nombre || "");
  const [fechaVencimiento, setFechaVencimiento] = useState(user.fecha_vencimiento || "");
  const [fechaRenovacion, setFechaRenovacion] = useState(user.fecha_renovacion || "");
  const [vitalicio, setVitalicio] = useState(!!user.vitalicio);
  const [pago, setPago] = useState(!!user.pago);
  const [alumno, setAlumno] = useState(!!user.alumno_comunidad);
  const [esAdmin, setEsAdmin] = useState(!!user.es_admin);
  const [esSenalero, setEsSenalero] = useState(!!user.es_senalero);
  const [nivelContenido, setNivelContenido] = useState(user.nivel_contenido || "prueba");
  const [aprobado, setAprobado] = useState(user.aprobado !== false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  const inputStyle = { backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` };

  const handleRenovacionChange = (value) => {
    setFechaRenovacion(value);
    if (value) setFechaVencimiento(addMonths(value, 3));
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await updateProfile(
        user.id,
        {
          nombre: nombre.trim(),
          fecha_vencimiento: fechaVencimiento || null,
          fecha_renovacion: fechaRenovacion || null,
          vitalicio,
          pago,
          alumno_comunidad: alumno,
          es_admin: esAdmin,
          es_senalero: esSenalero,
          nivel_contenido: nivelContenido,
          aprobado,
        },
        accessToken
      );
      onSaved();
      onClose();
    } catch (err) {
      setError(err.message || "No se pudo guardar");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center"
      style={{ backgroundColor: "rgba(0,0,0,0.6)" }}
      onClick={onClose}
    >
      <div
        className="rounded-t-3xl w-full max-w-md p-6 max-h-[85vh] overflow-y-auto"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, borderBottom: "none" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <span className="text-[15px] font-semibold" style={{ color: C.text }}>Editar usuario</span>
          <button onClick={onClose}>
            <X size={20} color={C.textDim} />
          </button>
        </div>

        <p className="text-xs mb-4" style={{ color: C.textDim }}>{user.email}</p>

        <div className="mb-3">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>NOMBRE</label>
          <input
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
            style={inputStyle}
          />
        </div>

        <div className="grid grid-cols-2 gap-3 mb-1">
          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>ÚLTIMA RENOVACIÓN</label>
            <input
              type="date"
              value={fechaRenovacion || ""}
              onChange={(e) => handleRenovacionChange(e.target.value)}
              className="w-full mt-1 rounded-xl px-3 py-3 text-sm outline-none"
              style={inputStyle}
            />
          </div>
          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>VENCIMIENTO</label>
            <input
              type="date"
              value={fechaVencimiento || ""}
              onChange={(e) => setFechaVencimiento(e.target.value)}
              disabled={vitalicio}
              className="w-full mt-1 rounded-xl px-3 py-3 text-sm outline-none"
              style={{ ...inputStyle, opacity: vitalicio ? 0.4 : 1 }}
            />
          </div>
        </div>
        <p className="text-[10px] mb-3" style={{ color: C.textDim }}>
          El vencimiento se calcula solo (renovación + 3 meses) — podés ajustarlo a mano si hace falta.
        </p>

        <div className="mb-3">
          <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
            NIVEL DE CONTENIDO
          </label>
          <select
            value={nivelContenido}
            onChange={(e) => setNivelContenido(e.target.value)}
            disabled={esAdmin}
            className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
            style={{ ...inputStyle, opacity: esAdmin ? 0.4 : 1 }}
          >
            {NIVELES_CONTENIDO.map((n) => (
              <option key={n.value} value={n.value}>{n.label}</option>
            ))}
          </select>
          {esAdmin && (
            <p className="text-[10px] mt-1" style={{ color: C.textDim }}>
              No aplica: es admin, ya tiene acceso a todo.
            </p>
          )}
          {vitalicio && !esAdmin && (
            <p className="text-[10px] mt-1" style={{ color: C.textDim }}>
              Vitalicio solo significa que no vence — igual elegí qué nivel de contenido tiene.
            </p>
          )}
        </div>

        {[
          { label: "Vitalicio", value: vitalicio, set: setVitalicio },
          { label: "Pagó (al día)", value: pago, set: setPago },
          { label: "Alumno de la comunidad", value: alumno, set: setAlumno },
          { label: "Puede cargar señales (sin ser admin)", value: esSenalero, set: setEsSenalero },
          { label: "Es admin", value: esAdmin, set: setEsAdmin },
          { label: "Habilitado (desmarcá para bloquear la cuenta)", value: aprobado, set: setAprobado },
        ].map((f) => (
          <button
            key={f.label}
            onClick={() => f.set(!f.value)}
            className="w-full flex items-center justify-between rounded-xl px-4 py-3 mb-2"
            style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
          >
            <span className="text-sm" style={{ color: C.text }}>{f.label}</span>
            <div
              className="w-10 h-5.5 rounded-full relative"
              style={{ backgroundColor: f.value ? C.green : C.border, height: 22, width: 40 }}
            >
              <div
                className="absolute top-0.5 rounded-full"
                style={{
                  backgroundColor: "#08090B",
                  width: 18,
                  height: 18,
                  transform: f.value ? "translateX(20px)" : "translateX(2px)",
                }}
              />
            </div>
          </button>
        ))}

        {error && <p className="text-sm text-center mt-2" style={{ color: C.red }}>{error}</p>}

        <button
          onClick={handleSave}
          disabled={saving}
          className="w-full rounded-2xl py-4 text-[15px] font-semibold mt-3"
          style={{ backgroundColor: C.green, color: "#08090B" }}
        >
          {saving ? "Guardando..." : "Guardar cambios"}
        </button>
      </div>
    </div>
  );
}

function UsuariosView({ onBack, accessToken, onApproved }) {
  const [users, setUsers] = useState([]);
  const [comprobantes, setComprobantes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingUser, setEditingUser] = useState(null);
  const [approvingId, setApprovingId] = useState(null);
  const [viewingImage, setViewingImage] = useState(null);
  const [actionError, setActionError] = useState(null);
  const [search, setSearch] = useState("");

  const load = () => {
    setLoading(true);
    Promise.all([fetchAllProfiles(accessToken), fetchPendingComprobantes(accessToken)])
      .then(([profilesData, comprobantesData]) => {
        setUsers(profilesData);
        setComprobantes(comprobantesData);
        setError(null);
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  };

  React.useEffect(() => {
    load();
  }, []);

  const searchLower = search.trim().toLowerCase();
  const usersFiltrados = searchLower
    ? users.filter(
        (u) =>
          (u.nombre || "").toLowerCase().includes(searchLower) ||
          (u.email || "").toLowerCase().includes(searchLower)
      )
    : users;

  const pendientes = usersFiltrados.filter((u) => u.aprobado === false);
  const aprobados = usersFiltrados.filter((u) => u.aprobado !== false);

  const quickApprove = async (u) => {
    setApprovingId(u.id);
    setActionError(null);
    try {
      await updateProfile(u.id, { aprobado: true }, accessToken);
      load();
      if (onApproved) onApproved();
    } catch (err) {
      setActionError(err.message || "No se pudo habilitar la cuenta");
    } finally {
      setApprovingId(null);
    }
  };

  const approveComprobante = async (c) => {
    setApprovingId(`c-${c.id}`);
    setActionError(null);
    try {
      const hoy = new Date().toISOString().slice(0, 10);
      const meses = c.plan_meses || 3;
      const nivelPlan = PLANES_PRO.find((p) => p.meses === meses)?.id || "esencial";
      const owner = users.find((u) => u.id === c.usuario_id);
      // Si todavía le quedaban días de vigencia (prueba u otra membresía), se los respetamos
      // sumando la nueva suscripción a partir de esa fecha, no desde hoy.
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const vencimientoActual = owner?.fecha_vencimiento ? new Date(owner.fecha_vencimiento + "T00:00:00") : null;
      const baseFecha = vencimientoActual && vencimientoActual > today ? owner.fecha_vencimiento : hoy;
      await updateComprobante(c.id, { estado: "aprobado" }, accessToken);
      await updateProfile(
        c.usuario_id,
        { pago: true, fecha_renovacion: hoy, fecha_vencimiento: addMonths(baseFecha, meses), nivel_contenido: nivelPlan },
        accessToken
      );
      load();
      if (onApproved) onApproved();
    } catch (err) {
      setActionError(err.message || "No se pudo aprobar el comprobante");
    } finally {
      setApprovingId(null);
    }
  };

  const rejectComprobante = async (c) => {
    setApprovingId(`c-${c.id}`);
    setActionError(null);
    try {
      await updateComprobante(c.id, { estado: "rechazado" }, accessToken);
      load();
      if (onApproved) onApproved();
    } catch (err) {
      setActionError(err.message || "No se pudo rechazar el comprobante");
    } finally {
      setApprovingId(null);
    }
  };

  const renderUserCard = (u, highlight) => {
    const status = computeSubStatus(u);
    const inicial = (u.nombre || u.email || "?").trim().charAt(0).toUpperCase();
    return (
      <div
        key={u.id}
        className="rounded-xl overflow-hidden"
        style={{ backgroundColor: C.card, border: `1px solid ${highlight ? "#F0B429" : C.border}` }}
      >
        <button onClick={() => setEditingUser(u)} className="w-full flex items-center gap-3 px-3 py-2.5 text-left">
          <div
            className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 text-xs font-bold"
            style={{ backgroundColor: C.cardAlt, color: C.textDim }}
          >
            {inicial}
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              <span className="font-semibold text-[13px] truncate" style={{ color: C.text }}>{u.nombre || "Sin nombre"}</span>
              {u.es_admin && <span className="text-[9px] font-bold px-1 rounded" style={{ backgroundColor: C.blueSoft, color: C.blue }}>ADMIN</span>}
            </div>
            <div className="text-[11px] truncate" style={{ color: C.textDim }}>{u.email}</div>
          </div>
          <span
            className="text-[10px] font-semibold px-2 py-1 rounded-full shrink-0 whitespace-nowrap"
            style={{ color: status.color, backgroundColor: `${status.color}22` }}
          >
            {status.label}
          </span>
        </button>
        {highlight && (
          <button
            onClick={() => quickApprove(u)}
            disabled={approvingId === u.id}
            className="w-full py-2 text-xs font-semibold"
            style={{ backgroundColor: C.green, color: "#08090B" }}
          >
            {approvingId === u.id ? "Habilitando..." : "✓ Habilitar cuenta"}
          </button>
        )}
      </div>
    );
  };

  const exportarCSV = () => {
    const headers = ["Nombre", "Email", "ID", "Fecha inicio", "Renovó", "Vence", "Estado", "Admin", "Alumno comunidad", "Discord", "Teléfono"];
    const rows = users.map((u) => {
      const status = computeSubStatus(u);
      return [
        u.nombre || "",
        u.email || "",
        u.id || "",
        u.fecha_inicio || "",
        u.fecha_renovacion || "",
        u.fecha_vencimiento || "",
        status.label,
        u.es_admin ? "Sí" : "No",
        u.alumno_comunidad ? "Sí" : "No",
        u.discord_usuario || "",
        u.telefono || "",
      ];
    });
    const csv = [headers, ...rows]
      .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
      .join("\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `usuarios-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="max-w-md mx-auto">
      <ScreenHeader title="Usuarios" onBack={onBack} />

      {!loading && !error && users.length > 0 && (
        <div className="relative mb-3">
          <Search size={15} color={C.textDim} className="absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nombre o email..."
            className="w-full rounded-xl pl-9 pr-3 py-2.5 text-sm outline-none"
            style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
          />
        </div>
      )}

      {!loading && !error && users.length > 0 && (
        <button
          onClick={exportarCSV}
          className="w-full flex items-center justify-center gap-2 rounded-xl py-2.5 mb-4 text-sm font-semibold"
          style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
        >
          <Download size={15} />
          Exportar a Excel/CSV
        </button>
      )}

      {loading && <p className="text-sm text-center py-10" style={{ color: C.textDim }}>Cargando usuarios...</p>}
      {!loading && error && <p className="text-sm text-center py-10" style={{ color: C.red }}>{error}</p>}
      {actionError && (
        <div
          className="rounded-xl px-4 py-3 mb-4 text-[12px] text-center"
          style={{ backgroundColor: C.redSoft, color: C.red, border: `1px solid ${C.red}66` }}
        >
          ⚠️ {actionError}
        </div>
      )}

      {!loading && !error && comprobantes.length > 0 && (
        <div className="mb-5">
          <div className="text-[11px] tracking-widest font-semibold mb-3" style={{ color: C.warningText }}>
            COMPROBANTES DE PAGO ({comprobantes.length})
          </div>
          <div className="flex flex-col gap-3">
            {comprobantes.map((c) => {
              const owner = users.find((u) => u.id === c.usuario_id);
              const planLabel = PLANES_PRO.find((p) => p.meses === c.plan_meses)?.label;
              const hoyPreview = new Date();
              hoyPreview.setHours(0, 0, 0, 0);
              const vencOwner = owner?.fecha_vencimiento ? new Date(owner.fecha_vencimiento + "T00:00:00") : null;
              const baseFechaPreview = vencOwner && vencOwner > hoyPreview ? owner.fecha_vencimiento : new Date().toISOString().slice(0, 10);
              return (
                <div key={c.id} className="rounded-2xl overflow-hidden" style={{ backgroundColor: C.card, border: "1px solid #F0B429" }}>
                  <button onClick={() => setViewingImage(c.imagen_url)} className="w-full">
                    <img src={c.imagen_url} alt="Comprobante" className="w-full h-32 object-cover" />
                  </button>
                  <div className="px-4 py-3">
                    <div className="font-semibold text-[13px] mb-0.5" style={{ color: C.text }}>
                      {owner?.nombre || "Usuario desconocido"}
                    </div>
                    <div className="text-xs mb-1" style={{ color: C.textDim }}>{owner?.email || c.usuario_id}</div>
                    {c.plan_meses && (
                      <div className="text-xs mb-3 font-medium" style={{ color: C.green }}>
                        Plan elegido: {planLabel || `${c.plan_meses} meses`} — vencería el {addMonths(baseFechaPreview, c.plan_meses)}
                        {vencOwner && vencOwner > hoyPreview ? " (respeta sus días vigentes)" : ""}
                      </div>
                    )}
                    {!c.plan_meses && (
                      <div className="text-xs mb-3" style={{ color: C.textDim }}>
                        No indicó plan — se va a usar 3 meses por defecto al aprobar.
                      </div>
                    )}
                    <div className="flex gap-2">
                      <button
                        onClick={() => approveComprobante(c)}
                        disabled={approvingId === `c-${c.id}`}
                        className="flex-1 rounded-xl py-2.5 text-sm font-semibold"
                        style={{ backgroundColor: C.green, color: "#08090B" }}
                      >
                        ✓ Aprobar
                      </button>
                      <button
                        onClick={() => rejectComprobante(c)}
                        disabled={approvingId === `c-${c.id}`}
                        className="flex-1 rounded-xl py-2.5 text-sm font-semibold"
                        style={{ backgroundColor: C.redSoft, color: C.red }}
                      >
                        ✕ Rechazar
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {!loading && !error && pendientes.length > 0 && (
        <div className="mb-5">
          <div className="text-[11px] tracking-widest font-semibold mb-3" style={{ color: C.warningText }}>
            CUENTAS BLOQUEADAS ({pendientes.length})
          </div>
          <div className="flex flex-col gap-2">
            {pendientes.map((u) => renderUserCard(u, true))}
          </div>
        </div>
      )}

      {!loading && !error && (
        <div>
          {pendientes.length > 0 && (
            <div className="text-[11px] tracking-widest font-semibold mb-3" style={{ color: C.textDim }}>
              TODOS LOS USUARIOS ({aprobados.length})
            </div>
          )}
          <div className="flex flex-col gap-2">
            {aprobados.map((u) => renderUserCard(u, false))}
            {users.length === 0 && (
              <p className="text-sm text-center py-10" style={{ color: C.textDim }}>No hay usuarios cargados todavía.</p>
            )}
            {users.length > 0 && usersFiltrados.length === 0 && (
              <p className="text-sm text-center py-10" style={{ color: C.textDim }}>Ningún usuario coincide con "{search}".</p>
            )}
          </div>
        </div>
      )}

      {editingUser && (
        <UserEditForm
          user={editingUser}
          accessToken={accessToken}
          onClose={() => setEditingUser(null)}
          onSaved={() => {
            load();
            if (onApproved) onApproved();
          }}
        />
      )}

      {viewingImage && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
          style={{ backgroundColor: "rgba(0,0,0,0.9)" }}
          onClick={() => setViewingImage(null)}
        >
          <img src={viewingImage} alt="Comprobante ampliado" className="max-w-full max-h-full rounded-xl" />
        </div>
      )}
    </div>
  );
}

function ConfiguracionView({ onBack, themeName, onSetTheme, nombre, setNombre, avatar, setAvatar, profile, onLogout, isAdmin, onOpenUsuarios, accessToken, onProfileUpdated }) {
  const status = computeSubStatus(profile);
  const [showProofForm, setShowProofForm] = useState(false);
  const [proofSent, setProofSent] = useState(false);
  const [showHistorial, setShowHistorial] = useState(false);
  const [showTermsPage, setShowTermsPage] = useState(false);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const [avatarError, setAvatarError] = useState(null);
  const [telefonoLocal, setTelefonoLocal] = useState(profile?.telefono || "");
  const [discordLocal, setDiscordLocal] = useState(profile?.discord_usuario || "");
  const [savingDatos, setSavingDatos] = useState(false);

  const handleAvatarFile = async (f) => {
    if (!f || !profile) return;
    const previewUrl = URL.createObjectURL(f);
    setAvatar(previewUrl);
    setUploadingAvatar(true);
    try {
      const url = await uploadAvatar(f);
      await updateProfile(profile.id, { avatar_url: url }, accessToken);
      setAvatar(url);
    } catch (err) {
      setAvatarError("No se pudo guardar la foto, probá de nuevo");
    } finally {
      setUploadingAvatar(false);
    }
  };
  const [datosSaved, setDatosSaved] = useState(false);
  const [datosError, setDatosError] = useState(null);

  const handleSaveDatos = async () => {
    setSavingDatos(true);
    setDatosError(null);
    setDatosSaved(false);
    try {
      const payload = {
        nombre: nombre.trim(),
        telefono: telefonoLocal.trim(),
        discord_usuario: discordLocal.trim() || null,
      };
      await updateProfile(profile.id, payload, accessToken);
      if (onProfileUpdated) onProfileUpdated(payload);
      setDatosSaved(true);
      setTimeout(() => setDatosSaved(false), 2500);
    } catch (err) {
      setDatosError(err.message || "No se pudieron guardar los cambios");
    } finally {
      setSavingDatos(false);
    }
  };

  if (showTermsPage) {
    return <TermsPageView onBack={() => setShowTermsPage(false)} />;
  }

  return (
    <div className="max-w-md mx-auto">
      <ScreenHeader title="Configuración" onBack={onBack} />

      <div className="flex flex-col items-center mb-6">
        <label
          className="relative cursor-pointer"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            const f = e.dataTransfer.files?.[0];
            if (f) handleAvatarFile(f);
          }}
        >
          <div
            className="w-24 h-24 rounded-full flex items-center justify-center overflow-hidden"
            style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
          >
            {avatar ? (
              <img src={avatar} alt="Foto de perfil" className="w-full h-full object-cover" />
            ) : (
              <Camera size={26} color={C.textDim} />
            )}
          </div>
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => handleAvatarFile(e.target.files?.[0])}
          />
          <div
            className="absolute bottom-0 right-0 w-7 h-7 rounded-full flex items-center justify-center"
            style={{ backgroundColor: C.green }}
          >
            <Camera size={13} color="#08090B" />
          </div>
        </label>
        <span className="text-xs mt-2" style={{ color: C.textDim }}>
          {uploadingAvatar ? "Guardando foto..." : "Foto de perfil"}
        </span>
        {avatarError && <span className="text-[11px] mt-1" style={{ color: C.red }}>{avatarError}</span>}
      </div>

      {profile && (
        <div className="rounded-2xl px-5 py-4 mb-4" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
          <div className="flex items-center justify-between mb-3">
            <span className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>MI SUSCRIPCIÓN</span>
            <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full" style={{ color: status.color, backgroundColor: `${status.color}22` }}>
              {status.label}
            </span>
          </div>
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-xs" style={{ color: C.textDim }}>Plan actual</span>
            <span className="text-sm font-semibold" style={{ color: C.text }}>{computePlanLabel(profile)}</span>
          </div>
          {!profile.vitalicio && (
            <>
              <div className="flex items-center justify-between mb-1.5">
                <span className="text-xs" style={{ color: C.textDim }}>Último pago</span>
                <span className="text-sm" style={{ color: C.text }}>{profile.fecha_renovacion || "—"}</span>
              </div>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs" style={{ color: C.textDim }}>Vence</span>
                <span className="text-sm font-semibold" style={{ color: status.color }}>{profile.fecha_vencimiento || "—"}</span>
              </div>
            </>
          )}
          {!profile.vitalicio && (
            <button
              onClick={() => setShowProofForm(true)}
              className="w-full rounded-xl py-2.5 text-sm font-semibold mb-2"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            >
              Subir comprobante de pago
            </button>
          )}
          <button
            onClick={() => setShowHistorial(true)}
            className="w-full rounded-xl py-2.5 text-sm font-semibold"
            style={{ backgroundColor: "transparent", color: C.textDim, border: `1px solid ${C.border}` }}
          >
            Ver historial de comprobantes
          </button>
        </div>
      )}

      {profile && (
        <div className="rounded-2xl px-5 py-4 mb-4" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
          <span className="text-[11px] tracking-wide font-medium mb-3 block" style={{ color: C.textDim }}>MIS DATOS</span>

          <div className="mb-3">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>NOMBRE</label>
            <input
              value={nombre}
              onChange={(e) => setNombre(e.target.value)}
              placeholder="Tu nombre"
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          <div className="mb-3">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>EMAIL</label>
            <input
              value={profile.email || ""}
              disabled
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none opacity-60"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          <div className="mb-3">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>TELÉFONO</label>
            <input
              value={telefonoLocal}
              onChange={(e) => setTelefonoLocal(e.target.value)}
              placeholder="+54 9 11 1234-5678"
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          <div className="mb-4">
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>USUARIO DE DISCORD</label>
            <input
              value={discordLocal}
              onChange={(e) => setDiscordLocal(e.target.value)}
              placeholder="tu_usuario"
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
            />
          </div>

          <button
            onClick={handleSaveDatos}
            disabled={savingDatos}
            className="w-full rounded-xl py-3 text-sm font-semibold"
            style={{ backgroundColor: C.green, color: "#08090B" }}
          >
            {savingDatos ? "Guardando..." : "Guardar cambios"}
          </button>
          {datosSaved && (
            <p className="text-[12px] text-center mt-2 font-medium" style={{ color: C.green }}>¡Datos guardados!</p>
          )}
          {datosError && (
            <p className="text-[12px] text-center mt-2" style={{ color: C.red }}>{datosError}</p>
          )}
        </div>
      )}

      <div className="rounded-2xl px-5 py-4 mb-3" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
        <span className="text-sm font-medium mb-3 block" style={{ color: C.text }}>
          Modo de color
        </span>
        <div className="flex gap-2">
          {[
            { v: "dark", l: "Oscuro", icon: Moon },
            { v: "medio", l: "Intermedio", icon: Sun },
            { v: "light", l: "Claro", icon: Sun },
          ].map((opt) => (
            <button
              key={opt.v}
              onClick={() => onSetTheme(opt.v)}
              className="flex-1 rounded-xl py-2.5 flex flex-col items-center gap-1"
              style={{
                backgroundColor: themeName === opt.v ? C.green : C.cardAlt,
                border: `1px solid ${themeName === opt.v ? C.green : C.border}`,
              }}
            >
              <opt.icon size={15} color={themeName === opt.v ? "#08090B" : C.textDim} />
              <span className="text-[11px] font-medium" style={{ color: themeName === opt.v ? "#08090B" : C.textDim }}>
                {opt.l}
              </span>
            </button>
          ))}
        </div>
      </div>

      <button
        onClick={() => setShowTermsPage(true)}
        className="w-full flex items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-semibold mb-3"
        style={{ backgroundColor: C.cardAlt, color: C.text, border: `1px solid ${C.border}` }}
      >
        <ShieldAlert size={16} />
        Volver a leer Términos y Condiciones
      </button>

      <button
        onClick={onLogout}
        className="w-full flex items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-semibold"
        style={{ backgroundColor: C.redSoft, color: C.red }}
      >
        <LogOut size={16} />
        Cerrar sesión
      </button>

      {proofSent && (
        <p className="text-[12px] text-center mt-3 font-medium" style={{ color: C.green }}>
          ¡Comprobante enviado! Un admin lo va a revisar pronto.
        </p>
      )}

      {showProofForm && profile && (
        <PaymentProofForm
          userId={profile.id}
          onClose={() => setShowProofForm(false)}
          onSent={() => setProofSent(true)}
        />
      )}

      {showHistorial && profile && (
        <HistorialComprobantesModal
          userId={profile.id}
          accessToken={accessToken}
          onClose={() => setShowHistorial(false)}
        />
      )}
    </div>
  );
}

function HistorialComprobantesModal({ userId, accessToken, onClose }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  React.useEffect(() => {
    fetchMyComprobantes(userId, accessToken)
      .then(setItems)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  const ESTADO_COMPROBANTE = {
    pendiente: { label: "Pendiente de revisión", color: "#F0B429" },
    aprobado: { label: "Aprobado", color: C.green },
    rechazado: { label: "Rechazado", color: C.red },
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center"
      style={{ backgroundColor: "rgba(0,0,0,0.6)" }}
      onClick={onClose}
    >
      <div
        className="rounded-t-3xl w-full max-w-md p-6 max-h-[80vh] overflow-y-auto"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, borderBottom: "none" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <span className="text-[15px] font-semibold" style={{ color: C.text }}>Historial de comprobantes</span>
          <button onClick={onClose}>
            <X size={20} color={C.textDim} />
          </button>
        </div>

        {loading && <p className="text-sm text-center py-8" style={{ color: C.textDim }}>Cargando...</p>}
        {!loading && error && <p className="text-sm text-center py-8" style={{ color: C.red }}>{error}</p>}
        {!loading && !error && items.length === 0 && (
          <p className="text-sm text-center py-8" style={{ color: C.textDim }}>Todavía no subiste ningún comprobante.</p>
        )}

        <div className="flex flex-col gap-3">
          {items.map((c) => {
            const estadoInfo = ESTADO_COMPROBANTE[c.estado] || { label: c.estado, color: C.textDim };
            const plan = PLANES_PRO.find((p) => p.meses === c.plan_meses);
            return (
              <div key={c.id} className="rounded-2xl overflow-hidden" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
                <img src={c.imagen_url} alt="Comprobante" className="w-full h-28 object-cover" />
                <div className="px-4 py-3">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-sm font-semibold" style={{ color: C.text }}>
                      {plan?.label || (c.plan_meses ? `${c.plan_meses} meses` : "Sin plan")}
                    </span>
                    <span
                      className="text-[10px] font-bold px-2 py-0.5 rounded-full"
                      style={{ backgroundColor: `${estadoInfo.color}22`, color: estadoInfo.color }}
                    >
                      {estadoInfo.label}
                    </span>
                  </div>
                  <div className="text-xs" style={{ color: C.textDim }}>
                    {c.created_at ? new Date(c.created_at).toLocaleDateString("es-AR") : ""}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function NodeExplorer({ seccion, rootTitle, isAdmin, onBack, layout = "grid", fixedRootItems = [], nivelUsuario = 99 }) {
  const [path, setPath] = useState([{ id: null, titulo: rootTitle, nivelReq: null }]);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [editingNode, setEditingNode] = useState(null);
  const [deletingId, setDeletingId] = useState(null);

  const current = path[path.length - 1];

  const load = () => {
    setLoading(true);
    fetchNodes(seccion, current.id)
      .then((data) => {
        const sorted = [...data].sort((a, b) => {
          const ao = a.orden ?? Number.MAX_SAFE_INTEGER;
          const bo = b.orden ?? Number.MAX_SAFE_INTEGER;
          return ao - bo;
        });
        setItems(sorted);
        setError(null);
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  };

  React.useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [current.id]);

  const handleBack = () => {
    if (path.length > 1) {
      setPath(path.slice(0, -1));
    } else {
      onBack();
    }
  };

  const nivelEfectivoDe = (node) => node.nivel_requerido || current.nivelReq || null;
  const estaBloqueado = (node) => {
    if (isAdmin) return false;
    const req = nivelEfectivoDe(node);
    return req ? nivelUsuario < rankNivel(req) : false;
  };

  const handleOpen = (node) => {
    if (estaBloqueado(node)) {
      alert(`Necesitás el nivel "${labelNivel(nivelEfectivoDe(node))}" o superior para acceder a esto.`);
      return;
    }
    if (node.tipo === "carpeta") {
      setPath([...path, { id: node.id, titulo: node.titulo, nivelReq: nivelEfectivoDe(node) }]);
    } else {
      window.open(node.url, "_blank", "noopener,noreferrer");
    }
  };

  const handleDelete = async (node) => {
    const msg =
      node.tipo === "carpeta"
        ? `¿Eliminar la carpeta "${node.titulo}"? Esto también borra todo lo que tenga adentro.`
        : `¿Eliminar "${node.titulo}"?`;
    if (!window.confirm(msg)) return;
    setDeletingId(node.id);
    try {
      await deleteNode(node.id);
      load();
    } catch (err) {
      alert(err.message || "No se pudo eliminar");
    } finally {
      setDeletingId(null);
    }
  };

  const handleMove = async (index, direction) => {
    const swapIdx = index + direction;
    if (swapIdx < 0 || swapIdx >= items.length) return;
    const reordered = [...items];
    [reordered[index], reordered[swapIdx]] = [reordered[swapIdx], reordered[index]];
    setItems(reordered);
    try {
      await Promise.all(reordered.map((item, i) => updateNodeOrder(item.id, i)));
    } catch (err) {
      alert(err.message || "No se pudo reordenar");
      load();
    }
  };

  const isGrid = layout === "grid";

  return (
    <div className="max-w-md mx-auto">
      <ScreenHeader title={current.titulo} onBack={handleBack} />

      {isAdmin && (
        <button
          onClick={() => setShowForm(true)}
          className="w-full rounded-2xl py-3 mb-4 text-sm font-semibold"
          style={{ backgroundColor: C.green, color: "#08090B" }}
        >
          + Agregar
        </button>
      )}

      {loading && <p className="text-sm text-center py-10" style={{ color: C.textDim }}>Cargando...</p>}
      {!loading && error && <p className="text-sm text-center py-10" style={{ color: C.red }}>{error}</p>}

      <div className={isGrid ? "grid grid-cols-2 gap-3" : "flex flex-col gap-3"}>
        {path.length === 1 && fixedRootItems.map((f, fi) => (
          <button
            key={`fixed-${fi}`}
            onClick={f.onClick}
            className="text-left rounded-2xl overflow-hidden"
            style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
          >
            <div
              className={isGrid ? "h-28 flex items-center justify-center overflow-hidden" : "h-24 flex items-center justify-center overflow-hidden"}
              style={{ backgroundColor: C.cardAlt, borderBottom: `1px solid ${C.borderSoft}` }}
            >
              <f.icon size={isGrid ? 24 : 30} color={C.green} />
            </div>
            <div className={isGrid ? "px-3 py-2.5 flex items-center justify-between gap-1" : "px-4 py-3 flex items-center justify-between"}>
              <div className={isGrid ? "font-medium text-[12px] leading-tight" : "font-semibold text-[14px]"} style={{ color: C.text }}>{f.titulo}</div>
              <ChevronRight size={16} color={C.textDim} className="shrink-0 ml-2" />
            </div>
          </button>
        ))}
        {!loading && !error && items.map((node, i) => {
          const isFolder = node.tipo === "carpeta";
          const thumb = node.miniatura_url || (!isFolder ? youtubeThumbFromUrl(node.url) : null);
          const TypeIcon = isFolder ? Folder : RESOURCE_TYPE_ICON[detectResourceType(node.url)];
          const bloqueado = estaBloqueado(node);
          const reqLabel = labelNivel(nivelEfectivoDe(node));
          return (
            <div
              key={node.id}
              className="relative rounded-2xl overflow-hidden"
              style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
            >
              <button onClick={() => handleOpen(node)} className="w-full text-left block">
                <div
                  className={isGrid ? "h-28 flex items-center justify-center overflow-hidden relative" : "h-24 flex items-center justify-center overflow-hidden relative"}
                  style={{ backgroundColor: C.cardAlt, borderBottom: `1px solid ${C.borderSoft}` }}
                >
                  {thumb ? (
                    <img src={thumb} alt="" className="w-full h-full object-cover" style={{ filter: bloqueado ? "grayscale(1) brightness(0.5)" : "none" }} />
                  ) : (
                    <TypeIcon size={isGrid ? 26 : 30} color={bloqueado ? C.textDim : C.green} />
                  )}
                  {bloqueado && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-1" style={{ backgroundColor: "rgba(0,0,0,0.45)" }}>
                      <Lock size={20} color="#fff" />
                      <span className="text-[9px] font-semibold px-1.5 py-0.5 rounded-full" style={{ backgroundColor: "#F0B429", color: "#08090B" }}>
                        {reqLabel}
                      </span>
                    </div>
                  )}
                </div>
                <div className={isGrid ? "px-3 py-2.5 flex items-center justify-between gap-1" : "px-4 py-3 flex items-center justify-between"}>
                  <div className={isGrid ? "font-medium text-[12px] leading-tight" : "font-semibold text-[14px]"} style={{ color: bloqueado ? C.textDim : C.text }}>{node.titulo}</div>
                  {!isGrid && (bloqueado ? <Lock size={15} color={C.textDim} className="shrink-0 ml-2" /> : isFolder ? <ChevronRight size={16} color={C.textDim} className="shrink-0 ml-2" /> : <ExternalLink size={16} color={C.textDim} className="shrink-0 ml-2" />)}
                </div>
              </button>
              {isAdmin && (
                <div className="absolute top-2 left-2 flex flex-col gap-1">
                  <button
                    onClick={() => handleMove(i, -1)}
                    disabled={i === 0}
                    className="w-6 h-6 rounded-full flex items-center justify-center"
                    style={{ backgroundColor: "rgba(0,0,0,0.55)", opacity: i === 0 ? 0.35 : 1 }}
                  >
                    <ChevronUp size={13} color="#fff" />
                  </button>
                  <button
                    onClick={() => handleMove(i, 1)}
                    disabled={i === items.length - 1}
                    className="w-6 h-6 rounded-full flex items-center justify-center"
                    style={{ backgroundColor: "rgba(0,0,0,0.55)", opacity: i === items.length - 1 ? 0.35 : 1 }}
                  >
                    <ChevronDown size={13} color="#fff" />
                  </button>
                </div>
              )}
              {isAdmin && (
                <button
                  onClick={() => handleDelete(node)}
                  disabled={deletingId === node.id}
                  className="absolute top-2 right-2 w-7 h-7 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: "rgba(0,0,0,0.55)" }}
                >
                  <X size={14} color="#fff" />
                </button>
              )}
              {isAdmin && (
                <button
                  onClick={() => setEditingNode(node)}
                  className="absolute bottom-2 right-2 w-7 h-7 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: "rgba(0,0,0,0.55)" }}
                >
                  <Pencil size={13} color="#fff" />
                </button>
              )}
            </div>
          );
        })}
        {!loading && !error && items.length === 0 && (
          <p className="text-sm text-center py-10 col-span-2" style={{ color: C.textDim }}>
            Todavía no hay nada cargado acá.
          </p>
        )}
      </div>

      {showForm && (
        <NodeForm
          seccion={seccion}
          parentId={current.id}
          onClose={() => setShowForm(false)}
          onCreated={load}
        />
      )}
      {editingNode && (
        <NodeForm
          seccion={seccion}
          parentId={current.id}
          editingNode={editingNode}
          onClose={() => setEditingNode(null)}
          onCreated={load}
        />
      )}
    </div>
  );
}

