function TickerTape({ themeName }) {
  const containerRef = React.useRef(null);

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    container.innerHTML = "";
    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js";
    script.async = true;
    script.innerHTML = JSON.stringify({
      symbols: [
        { proName: "TVC:USOIL", title: "Petróleo" },
        { proName: "BITSTAMP:BTCUSD", title: "Bitcoin" },
        { proName: "BITSTAMP:ETHUSD", title: "Ethereum" },
        { proName: "FOREXCOM:SPXUSD", title: "S&P 500" },
      ],
      showSymbolLogo: true,
      isTransparent: true,
      displayMode: "adaptive",
      colorTheme: themeName === "light" ? "light" : "dark",
      locale: "es",
    });
    container.appendChild(script);
  }, [themeName]);

  return (
    <div style={{ backgroundColor: C.card, borderBottom: `1px solid ${C.border}` }}>
      <div ref={containerRef} className="tradingview-widget-container" />
    </div>
  );
}


export default function App() {
  const [themeName, setThemeName] = useState("dark");
  applyTheme(themeName);

  React.useEffect(() => {
    document.title = "Trader App";
  }, []);

  const [session, setSession] = useState(null); // { accessToken, userId, profile }
  const [restoringSession, setRestoringSession] = useState(true);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [previewLocked, setPreviewLocked] = useState(false);
  const exitingRef = useRef(false);
  const popHandlerRef = useRef(null);

  React.useEffect(() => {
    if (!session) return;
    window.history.pushState({ appGuard: true }, "");
    const handler = () => {
      if (exitingRef.current) return;
      window.history.pushState({ appGuard: true }, "");
      setShowExitConfirm(true);
    };
    popHandlerRef.current = handler;
    window.addEventListener("popstate", handler);
    return () => window.removeEventListener("popstate", handler);
  }, [session]);

  const handleConfirmExit = () => {
    exitingRef.current = true;
    setShowExitConfirm(false);
    if (popHandlerRef.current) window.removeEventListener("popstate", popHandlerRef.current);
    window.history.go(-2);
  };

  const [showPersonalDataPopup, setShowPersonalDataPopup] = useState(false);
  const [activeFlyers, setActiveFlyers] = useState([]);
  const [flyerDismissed, setFlyerDismissed] = useState(false);
  const [personalDataDismissed, setPersonalDataDismissed] = useState(false);
  const [tab, setTab] = useState("home");
  const [herramientasView, setHerramientasView] = useState(null);
  const [masSection, setMasSection] = useState(null); // null | "formacion" | "comunidad-productos"
  const [formacionView, setFormacionView] = useState(null);
  const [comunidadView, setComunidadView] = useState(null);
  const [tiendaView, setTiendaView] = useState(null);
  const [adminPanelView, setAdminPanelView] = useState(null); // null | "usuarios" (más ítems admin se suman después)
  const [specialView, setSpecialView] = useState(null); // null | "config" | "usuarios"
  const [view, setView] = useState("list");
  const [selectedId, setSelectedId] = useState(null);
  const [risk, setRisk] = useState(1);
  const [filter, setFilter] = useState("Todas");
  const filterScrollRef = useRef(null);
  const scrollFilters = (dir) => {
    if (filterScrollRef.current) {
      filterScrollRef.current.scrollBy({ left: dir * 160, behavior: "smooth" });
    }
  };

  const [signals, setSignals] = useState([]);
  const [loadingSignals, setLoadingSignals] = useState(true);
  const [errorSignals, setErrorSignals] = useState(null);
  const [showAdminForm, setShowAdminForm] = useState(false);
  const [nombre, setNombre] = useState("");
  const [avatar, setAvatar] = useState(null);
  const [editingSignal, setEditingSignal] = useState(null);

  const [pendingCount, setPendingCount] = useState(0);
  const [pendingComprobantesCount, setPendingComprobantesCount] = useState(0);

  const refreshPendingCount = async (accessToken) => {
    const [count, comprobantes] = await Promise.all([
      fetchPendingCount(accessToken),
      fetchPendingComprobantes(accessToken).catch(() => []),
    ]);
    setPendingCount(count);
    setPendingComprobantesCount(comprobantes.length);
  };

  React.useEffect(() => {
    const stored = loadSessionFromStorage();
    if (!stored) {
      setRestoringSession(false);
      return;
    }
    (async () => {
      try {
        const profile = await fetchProfile(stored.userId, stored.accessToken);
        setSession({ accessToken: stored.accessToken, userId: stored.userId, profile });
        setNombre(profile?.nombre || ""); setAvatar(profile?.avatar_url || null);
        if (profile?.es_admin) refreshPendingCount(stored.accessToken);
      } catch (err) {
        try {
          const data = await refreshSupabaseSession(stored.refreshToken);
          const profile = await fetchProfile(data.user.id, data.access_token);
          saveSessionToStorage(data.access_token, data.refresh_token, data.user.id);
          setSession({ accessToken: data.access_token, userId: data.user.id, profile });
          setNombre(profile?.nombre || ""); setAvatar(profile?.avatar_url || null);
          if (profile?.es_admin) refreshPendingCount(data.access_token);
        } catch (err2) {
          clearStoredSession();
        }
      } finally {
        setRestoringSession(false);
      }
    })();
  }, []);

  const handleLogin = async (email, password) => {
    const data = await loginWithSupabase(email, password);
    let profile = await fetchProfile(data.user.id, data.access_token);
    if (!profile) {
      // Auto-reparación: existe el login pero falta la ficha en "profiles" (por ej. un registro que se cortó a mitad de camino)
      try {
        const hoy = new Date().toISOString().slice(0, 10);
        const rows = await createProfileRow(data.user.id, {
          email,
          fecha_inicio: hoy,
          fecha_vencimiento: addDays(hoy, 10),
          pago: false,
          aprobado: !REQUIRE_APPROVAL,
          es_admin: false,
        });
        profile = rows[0] || null;
      } catch (err) {
        // si falla igual, seguimos con profile = null y quedará bloqueado por seguridad
      }
    }
    setSession({ accessToken: data.access_token, userId: data.user.id, profile });
    setNombre(profile?.nombre || ""); setAvatar(profile?.avatar_url || null);
    saveSessionToStorage(data.access_token, data.refresh_token, data.user.id);
    if (!profile || profile.aprobado === false) return; // queda bloqueado en PendingApprovalView
    if (profile?.es_admin) refreshPendingCount(data.access_token);
    setTab("home");
  };

  const handleSignup = async (email, password, nombreCompleto, esComunidad, discordUsuario) => {
    const data = await signupWithSupabase(email, password);
    const hoy = new Date().toISOString().slice(0, 10);
    await createProfileRow(data.user.id, {
      nombre: nombreCompleto,
      email,
      fecha_inicio: hoy,
      fecha_vencimiento: addDays(hoy, 10),
      pago: false,
      aprobado: !REQUIRE_APPROVAL,
      es_admin: false,
      alumno_comunidad: esComunidad,
      discord_usuario: discordUsuario || null,
    });
    await registerTermsAcceptanceAtSignup(data.user.id);
  };

  const handleLogout = () => {
    setSession(null);
    clearStoredSession();
    setTab("home");
    setSpecialView(null);
    setHerramientasView(null);
    setMasSection(null);
    setFormacionView(null);
    setComunidadView(null);
    setTiendaView(null);
    setAdminPanelView(null);
    setPersonalDataDismissed(false);
    setFlyerDismissed(false);
  };

  const isAdmin = !!session?.profile?.es_admin;
  const isSenalero = !!session?.profile?.es_senalero;
  const canManageSignals = isAdmin || isSenalero;

  const loadSignals = () => {
    setLoadingSignals(true);
    fetchSignals()
      .then((data) => {
        setSignals(data);
        setErrorSignals(null);
      })
      .catch((err) => {
        setErrorSignals(err.message || "No se pudieron cargar las señales");
      })
      .finally(() => {
        setLoadingSignals(false);
      });
  };

  useEffect(() => {
    loadSignals();
    fetchActiveFlyers().then(setActiveFlyers).catch(() => {});
  }, []);

  const filtered = signals.filter((s) => {
    if (filter === "Todas") return true;
    if (filter === "Activas") return s.estado === "activa";
    if (filter === "Pendientes") return s.estado === "pendiente";
    if (filter === "Cerradas") return s.estado === "ganada" || s.estado === "perdida" || s.estado === "be" || s.estado === "descartada";
    return s.par === filter;
  });

  const stats = computeStats(filtered);

  const goHome = () => {
    setTab("home");
    setView("list");
    setHerramientasView(null);
    setMasSection(null);
    setFormacionView(null);
    setComunidadView(null);
    setTiendaView(null);
    setSpecialView(null);
    setAdminPanelView(null);
  };

  const openSignal = (sig) => {
    setSelectedId(sig.id);
    setView("detail");
    setTab("senales");
  };
  const selected = signals.find((s) => s.id === selectedId) || null;

  if (restoringSession) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ backgroundColor: C.bg }}>
        <span style={{ color: C.textDim }}>Cargando...</span>
      </div>
    );
  }
  if (!session) {
    return <LoginView onLogin={handleLogin} onSignup={handleSignup} />;
  }
  if (!session.profile || session.profile.aprobado === false) {
    return <PendingApprovalView onLogout={handleLogout} />;
  }
  const vencidoBloqueante = !isAdmin && computeSubStatus(session.profile).label === "Vencida";
  if (vencidoBloqueante && !previewLocked) {
    return (
      <SubscriptionExpiredView
        userId={session.userId}
        accessToken={session.accessToken}
        onLogout={handleLogout}
        onEnterPreview={() => setPreviewLocked(true)}
      />
    );
  }

  const needsPersonalData =
    !isAdmin &&
    session.profile &&
    (!session.profile.nombre?.trim() || !session.profile.telefono?.trim()) &&
    !personalDataDismissed;

  const bloqueadoPorVencimiento = vencidoBloqueante && previewLocked;

  return (
    <>
    <div
      className="min-h-screen flex flex-col"
      style={{
        backgroundColor: C.bg,
        ...(bloqueadoPorVencimiento
          ? { filter: "grayscale(1) brightness(0.55)", pointerEvents: "none", userSelect: "none" }
          : {}),
      }}
    >
      <TopBar
        nombre={nombre}
        avatar={avatar}
        isAdmin={isAdmin}
        adminPendingTotal={pendingCount + pendingComprobantesCount}
        onOpenAdminAlerts={() => setSpecialView("usuarios")}
        onOpenConfig={() => setSpecialView("config")}
        onLogoClick={goHome}
      />
      <TickerTape themeName={themeName} />
      <div className="flex-1 px-4 py-6 pb-40">
        <div className="max-w-md mx-auto">
          {specialView === null && (
          <>
          {tab === "senales" && view === "list" && (
            <>
              <button onClick={goHome} className="flex items-center gap-1.5 mb-3">
                <ArrowLeft size={19} color={C.textDim} />
                <span className="text-[13px] font-medium" style={{ color: C.textDim }}>Volver</span>
              </button>
              <div className="relative flex items-center justify-center mb-4">
                <div className="text-[14px] tracking-widest font-bold text-center" style={{ color: C.text }}>
                  SEÑALES
                </div>
                {canManageSignals && (
                  <button
                    onClick={() => setShowAdminForm(true)}
                    className="absolute right-0 w-9 h-9 rounded-full flex items-center justify-center"
                    style={{ backgroundColor: C.green }}
                    aria-label="Nueva señal"
                  >
                    <Plus size={18} color="#08090B" />
                  </button>
                )}
              </div>
              {(() => {
                const daysLeft = daysUntilVencimiento(session.profile);
                if (daysLeft === null || daysLeft > 15) return null;
                const vencida = daysLeft < 0;
                return (
                  <div
                    className="rounded-xl px-4 py-3 mb-4 text-[12px] text-center"
                    style={{
                      backgroundColor: vencida ? C.redSoft : C.warningBg,
                      color: vencida ? C.red : C.warningText,
                      border: `1px solid ${vencida ? C.red : C.warningBorder}`,
                    }}
                  >
                    {vencida
                      ? `⚠️ Tu suscripción venció el ${session.profile.fecha_vencimiento}. Actualizá tu pago para reactivar tu cuenta.`
                      : `⚠️ Tu suscripción vence el ${session.profile.fecha_vencimiento} (en ${daysLeft} ${daysLeft === 1 ? "día" : "días"}). Renová para no perder el acceso.`}
                  </div>
                );
              })()}
              <div
                className="rounded-xl px-4 py-3 mb-4 text-[11px] text-center"
                style={{ backgroundColor: "rgba(247,100,100,0.10)", color: C.red, border: `1px solid ${C.red}66` }}
              >
                ⚠️ El trading implica riesgos. Esta aplicación ofrece contenido educativo e informativo, no asesoramiento financiero. Cada usuario es responsable de sus decisiones, operaciones y gestión de capital.
              </div>
              <button
                onClick={() => {
                  setTab("mas");
                  setMasSection("formacion");
                  setFormacionView("videos");
                }}
                className="w-full text-center text-[12px] font-medium py-2.5 px-4 rounded-xl mb-4"
                style={{ backgroundColor: C.blueSoft, color: C.blue }}
              >
                SI NO SABÉS CÓMO COLOCAR LA SEÑAL, HACÉ CLIC ACÁ Y MIRÁ EL TUTORIAL
              </button>
              <div className="relative flex items-center gap-1 mb-4">
                <button
                  onClick={() => scrollFilters(-1)}
                  className="shrink-0 flex items-center justify-center w-6 h-6 rounded-full"
                  style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
                >
                  <ChevronLeft size={14} color={C.textDim} />
                </button>
                <div ref={filterScrollRef} className="flex gap-2 overflow-x-auto pb-1 scroll-smooth" style={{ scrollbarWidth: "none" }}>
                  {["Todas", "Activas", "Pendientes", "Cerradas", ...Array.from(new Set(signals.map((s) => s.par))).sort()].map((f) => (
                    <button
                      key={f}
                      onClick={() => setFilter(f)}
                      className="px-4 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors"
                      style={{
                        backgroundColor: filter === f ? C.green : "transparent",
                        color: filter === f ? "#08090B" : C.textDim,
                        border: filter === f ? "none" : `1px solid ${C.border}`,
                      }}
                    >
                      {f}
                    </button>
                  ))}
                </div>
                <button
                  onClick={() => scrollFilters(1)}
                  className="shrink-0 flex items-center justify-center w-6 h-6 rounded-full"
                  style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
                >
                  <ChevronRight size={14} color={C.textDim} />
                </button>
              </div>
              {loadingSignals && (
                <div className="text-center text-sm py-10" style={{ color: C.textDim }}>
                  Cargando señales...
                </div>
              )}
              {!loadingSignals && errorSignals && (
                <div
                  className="text-center text-sm py-6 px-4 rounded-2xl"
                  style={{ color: C.red, backgroundColor: C.card, border: `1px solid ${C.border}` }}
                >
                  No se pudieron cargar las señales: {errorSignals}
                </div>
              )}
              <div className="grid grid-cols-2 gap-3">
                {!loadingSignals && !errorSignals && filtered.map((s) => (
                  <SignalCard key={s.id} signal={s} onOpen={openSignal} compact />
                ))}
              </div>
              {!loadingSignals && !errorSignals && filtered.length === 0 && (
                <div className="text-center text-sm py-10" style={{ color: C.textDim }}>
                  Todavía no hay señales cargadas.
                </div>
              )}
            </>
          )}

          {tab === "senales" && view === "detail" && (
            <DetailView
              signal={selected}
              onBack={() => setView("list")}
              risk={risk}
              onEdit={() => setEditingSignal(selected)}
              isAdmin={canManageSignals}
            />
          )}

          {tab === "home" && (
            <InicioDashboard
              signals={signals}
              isAdmin={isAdmin}
              profile={session.profile}
              onOpenSignal={openSignal}
              onNuevaSenal={() => setShowAdminForm(true)}
              onDesbloquearPro={() => setSpecialView("planes")}
              onOpenBitacora={() => setSpecialView("bitacora")}
              onNavigate={(t, extra) => {
                setTab(t);
                if (extra?.herramientasView) setHerramientasView(extra.herramientasView);
                setMasSection(extra?.masSection || null);
              }}
            />
          )}

          {tab === "broker" && (
            <BrokerView onBack={goHome} isAdmin={isAdmin} nivelUsuario={nivelEfectivoUsuario(session.profile)} />
          )}

          {tab === "herramientas" && (
            <NodeExplorer seccion="herramientas" rootTitle="Herramientas" isAdmin={isAdmin} onBack={goHome} layout="grid" nivelUsuario={nivelEfectivoUsuario(session.profile)} />
          )}

          {tab === "automatizaciones" && (
            <NodeExplorer
              seccion="automatizaciones"
              rootTitle="Automatizaciones / EAs (MT5 - TradingView)"
              isAdmin={isAdmin}
              onBack={goHome}
              layout="grid"
              nivelUsuario={nivelEfectivoUsuario(session.profile)}
            />
          )}

          {tab === "mas" && masSection === null && (
            <MasMenu
              onSelect={setMasSection}
              onBack={goHome}
              isAdmin={isAdmin}
              pendingTotal={pendingCount + pendingComprobantesCount}
            />
          )}

          {tab === "mas" && masSection === "administracion" && isAdmin && adminPanelView === null && (
            <div className="max-w-md mx-auto">
              <ScreenHeader title="Administración" onBack={() => setMasSection(null)} />
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => setAdminPanelView("usuarios")}
                  className="relative h-28 rounded-2xl px-3 flex flex-col items-center justify-center gap-2 text-center"
                  style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
                >
                  <UserCog size={20} color={C.green} />
                  <span className="font-medium text-[13px] leading-tight" style={{ color: C.text }}>Usuarios y suscripciones</span>
                  {pendingCount + pendingComprobantesCount > 0 && (
                    <span
                      className="absolute top-2 right-2 text-[10px] font-bold px-1.5 py-0.5 rounded-full"
                      style={{ backgroundColor: "#F0B429", color: "#08090B" }}
                    >
                      {pendingCount + pendingComprobantesCount}
                    </span>
                  )}
                </button>
                <button
                  onClick={() => setAdminPanelView("flyer")}
                  className="h-28 rounded-2xl px-3 flex flex-col items-center justify-center gap-2 text-center"
                  style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
                >
                  <ImageIcon size={20} color={C.green} />
                  <span className="font-medium text-[13px] leading-tight" style={{ color: C.text }}>Flyer / Promociones</span>
                </button>
              </div>
              <p className="text-[11px] text-center mt-4" style={{ color: C.textDim }}>
                Vamos a sumar más paneles administrativos acá a medida que los definamos.
              </p>
            </div>
          )}
          {tab === "mas" && masSection === "administracion" && isAdmin && adminPanelView === "usuarios" && (
            <UsuariosView
              onBack={() => setAdminPanelView(null)}
              accessToken={session.accessToken}
              onApproved={() => refreshPendingCount(session.accessToken)}
            />
          )}
          {tab === "mas" && masSection === "administracion" && isAdmin && adminPanelView === "flyer" && (
            <FlyerAdminView onBack={() => setAdminPanelView(null)} accessToken={session.accessToken} />
          )}

          {tab === "mas" && masSection === "formacion" && (
            <ClasesGrabadasView onBack={goHome} isAdmin={isAdmin} nivelUsuario={nivelEfectivoUsuario(session.profile)} />
          )}

          {tab === "mas" && masSection === "comunidad" && comunidadView === null && (
            <NodeExplorer
              seccion="comunidad"
              rootTitle="Comunidad Operación Trading"
              isAdmin={isAdmin}
              onBack={goHome}
              layout="grid"
              nivelUsuario={nivelEfectivoUsuario(session.profile)}
              fixedRootItems={[
                { titulo: "Discord y traders", icon: MessageCircle, onClick: () => setComunidadView("discord") },
                { titulo: "Noticias internas", icon: Bell, onClick: () => setComunidadView("noticias-internas") },
              ]}
            />
          )}
          {tab === "mas" && masSection === "comunidad" && comunidadView === "discord" && (
            <ComunidadSubView onBack={() => setComunidadView(null)} />
          )}
          {tab === "mas" && masSection === "comunidad" && comunidadView === "noticias-internas" && (
            <NovedadesSubView onBack={() => setComunidadView(null)} isAdmin={isAdmin} />
          )}

          {tab === "mas" && masSection === "tienda" && (
            <NodeExplorer seccion="tienda" rootTitle="Tienda" isAdmin={isAdmin} onBack={goHome} layout="grid" nivelUsuario={nivelEfectivoUsuario(session.profile)} />
          )}

          {tab === "mas" && masSection === "calendario-mas" && (
            <CalendarioEconomicoWrap themeName={themeName} onBack={goHome} />
          )}
          {tab === "mas" && masSection === "soporte" && (
            <div className="max-w-md mx-auto">
              <ScreenHeader title="Soporte" onBack={goHome} />

              <div className="mb-4">
                <div className="text-[15px] font-bold mb-1" style={{ color: C.text }}>
                  Estamos para ayudarte.
                </div>
                <p className="text-sm" style={{ color: C.textDim }}>
                  Dejanos tu consulta con la mayor cantidad de información posible para que podamos revisarla correctamente.
                </p>
              </div>

              <div
                className="rounded-2xl p-4 mb-4"
                style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}
              >
                <div className="flex items-center gap-2 mb-1.5">
                  <span className="text-base">⏱️</span>
                  <span className="text-[13px] font-semibold" style={{ color: C.text }}>Tiempo de respuesta</span>
                </div>
                <p className="text-xs" style={{ color: C.textDim }}>
                  Nuestro equipo responde las consultas en un plazo de hasta 24 horas. Te pedimos paciencia y evitar
                  enviar la misma consulta varias veces, ya que esto puede demorar la atención.
                </p>
              </div>

              <div
                className="rounded-2xl p-4 mb-4"
                style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
              >
                <div className="text-[11px] tracking-widest font-semibold mb-3" style={{ color: C.textDim }}>
                  ANTES DE ENVIAR TU CONSULTA
                </div>
                <div className="flex flex-col gap-2.5">
                  {[
                    { icon: MessageCircle, texto: "Describí el problema con el mayor detalle posible" },
                    { icon: Camera, texto: "Adjuntá una captura de pantalla si es necesario" },
                    { icon: CalendarDays, texto: "Esperá nuestra respuesta dentro de las próximas 24 h" },
                  ].map((item, i) => (
                    <div key={i} className="flex items-start gap-2.5">
                      <div
                        className="w-6 h-6 rounded-full flex items-center justify-center shrink-0 mt-0.5"
                        style={{ backgroundColor: C.greenSoft }}
                      >
                        <item.icon size={12} color={C.green} />
                      </div>
                      <span className="text-[13px]" style={{ color: C.text }}>{item.texto}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="rounded-2xl p-6 text-center" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                <p className="text-sm mb-4" style={{ color: C.textDim }}>
                  ¿Tenés una duda o un problema con la app? Escribinos directo por WhatsApp.
                </p>
                <a
                  href="https://wa.me/59175800153"
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center gap-2 rounded-xl px-5 py-3 text-sm font-semibold"
                  style={{ backgroundColor: "#25D366", color: "#08090B" }}
                >
                  💬 Contactar por WhatsApp
                </a>
              </div>
            </div>
          )}

          </>
          )}

          {specialView === "usuarios" && isAdmin && (
            <UsuariosView
              onBack={() => setSpecialView(null)}
              accessToken={session.accessToken}
              onApproved={() => refreshPendingCount(session.accessToken)}
            />
          )}
          {specialView === "planes" && (
            <PlanesProView
              onBack={() => setSpecialView(null)}
              userId={session.userId}
              accessToken={session.accessToken}
            />
          )}
          {specialView === "bitacora" && (
            <BitacoraRoot session={session} onBack={() => setSpecialView(null)} />
          )}
          {specialView === "config" && (
            <ConfiguracionView
              onBack={() => setSpecialView(null)}
              themeName={themeName}
              onSetTheme={setThemeName}
              nombre={nombre}
              setNombre={setNombre}
              avatar={avatar}
              setAvatar={setAvatar}
              profile={session.profile}
              onLogout={handleLogout}
              isAdmin={isAdmin}
              onOpenUsuarios={() => setSpecialView("usuarios")}
              accessToken={session.accessToken}
              onProfileUpdated={(payload) =>
                setSession((s) => ({ ...s, profile: { ...s.profile, ...payload } }))
              }
            />
          )}
        </div>
      </div>

      {showAdminForm && (
        <AdminForm onClose={() => setShowAdminForm(false)} onCreated={loadSignals} />
      )}

      {showExitConfirm && (
        <div
          className="fixed inset-0 z-[100] flex items-center justify-center p-6"
          style={{ backgroundColor: "rgba(0,0,0,0.65)" }}
        >
          <div
            className="rounded-2xl p-5 w-full max-w-xs text-center"
            style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
          >
            <div className="font-semibold text-[16px] mb-1" style={{ color: C.text }}>¿Salir de la app?</div>
            <p className="text-sm mb-5" style={{ color: C.textDim }}>
              Vas a cerrar Operación Trading.
            </p>
            <div className="flex gap-2">
              <button
                onClick={() => setShowExitConfirm(false)}
                className="flex-1 rounded-xl py-3 text-sm font-medium"
                style={{ backgroundColor: C.cardAlt, color: C.text }}
              >
                Cancelar
              </button>
              <button
                onClick={handleConfirmExit}
                className="flex-1 rounded-xl py-3 text-sm font-semibold"
                style={{ backgroundColor: C.red, color: "#fff" }}
              >
                Salir
              </button>
            </div>
          </div>
        </div>
      )}

      {editingSignal && (
        <AdminForm
          existingSignal={editingSignal}
          onClose={() => setEditingSignal(null)}
          onCreated={loadSignals}
          onDeleted={() => {
            setEditingSignal(null);
            setSelectedId(null);
            setView("list");
            loadSignals();
          }}
        />
      )}
      {needsPersonalData && (
        <PersonalDataPopup
          profile={session.profile}
          accessToken={session.accessToken}
          onClose={() => setPersonalDataDismissed(true)}
          onSaved={(nuevoNombre) => {
            setNombre(nuevoNombre);
            setSession((s) => ({ ...s, profile: { ...s.profile, nombre: nuevoNombre } }));
          }}
        />
      )}

      {activeFlyers.length > 0 && !flyerDismissed && !needsPersonalData && (
        <FlyerPopup flyers={activeFlyers} onClose={() => setFlyerDismissed(true)} />
      )}

      <div
        className="fixed left-0 right-0 flex flex-col items-center justify-center gap-0.5 py-1.5 px-4"
        style={{ bottom: 64, backgroundColor: C.bg, borderTop: `1px solid ${C.borderSoft}` }}
      >
        <span className="text-[10px] tracking-widest font-semibold" style={{ color: C.textDim }}>
          DISCIPLINA&nbsp;&nbsp;|&nbsp;&nbsp;PACIENCIA&nbsp;&nbsp;|&nbsp;&nbsp;CONSTANCIA
        </span>
        <span className="text-[9px] text-center" style={{ color: C.textDim }}>
          © Todos los derechos reservados a Operación Trading.
        </span>
      </div>

      <div
        className="fixed bottom-0 left-0 right-0 flex justify-around items-center py-2"
        style={{ backgroundColor: C.card, borderTop: `1px solid ${C.border}` }}
      >
        {TABS.map((t) => {
          const Icon = t.icon;
          const active = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => {
                setTab(t.id);
                setSpecialView(null);
                if (t.id === "senales") setView("list");
                if (t.id === "herramientas") setHerramientasView(null);
                if (t.id === "mas") {
                  setMasSection(null);
                  setFormacionView(null);
                  setComunidadView(null);
    setTiendaView(null);
                  setAdminPanelView(null);
                }
              }}
              className="flex flex-col items-center gap-0.5 px-1 py-1 flex-1 min-w-0"
            >
              <Icon size={19} color={active ? C.green : C.textDim} />
              <span className="text-[8.5px] whitespace-nowrap" style={{ color: active ? C.green : C.textDim }}>{t.label}</span>
            </button>
          );
        })}
      </div>
    </div>
    {bloqueadoPorVencimiento && (
      <div
        className="fixed bottom-0 left-0 right-0 z-[200] px-5 py-4 flex flex-col items-center gap-3"
        style={{ backgroundColor: C.card, borderTop: `1px solid ${C.border}` }}
      >
        <p className="text-sm text-center font-medium" style={{ color: C.text }}>
          ⏳ Tu cuenta está pendiente de aprobación. Podés mirar la app, pero no vas a poder usarla hasta que un admin confirme tu pago.
        </p>
        <button
          onClick={() => setPreviewLocked(false)}
          className="w-full max-w-xs rounded-2xl py-3 text-sm font-semibold"
          style={{ backgroundColor: C.green, color: "#08090B" }}
        >
          Volver
        </button>
      </div>
    )}
    </>
  );
}
